def page_security(lang, t):
    """Security and privacy, on the design system."""
    import ui
    H = (T("Your trading history, safe and yours.","Ton historique de trading, en sécurité et à toi.","Tu historial de trading, seguro y tuyo."),
        T("What Sweep stores, how it’s protected, and how to take it with you or delete it. In plain words.","Ce que Sweep conserve, comment c’est protégé, et comment l’emporter ou le supprimer. En mots simples.","Qué guarda Sweep, cómo se protege y cómo llevártelo o eliminarlo. En palabras simples."),
        T("Security and privacy","Sécurité et confidentialité","Seguridad y privacidad"))
    items = [("archive",T("Lose an account, keep your history","Perds un compte, garde ton historique","Pierdes una cuenta, conservas tu historial"),T("Closing or failing a prop account never deletes your history. Export everything in one click, anytime.","Fermer ou échouer un compte prop ne supprime jamais ton historique. Exporte tout en un clic, à tout moment.","Cerrar o fallar una cuenta prop nunca borra tu historial. Exporta todo en un clic, cuando quieras.")),
        ("lock",T("Payments by Stripe","Paiements par Stripe","Pagos con Stripe"),T("Payments are processed by Stripe. Sweep never sees or stores your card number.","Les paiements sont traités par Stripe. Sweep ne voit ni ne stocke jamais ton numéro de carte.","Los pagos los procesa Stripe. Sweep nunca ve ni guarda el número de tu tarjeta.")),
        ("eye",T("Only you see your data","Toi seul vois tes données","Solo tú ves tus datos"),T("Each trader’s data is separate. The admin page shows usernames and usage, never trades or notes.","Les données de chaque trader sont séparées. La page admin montre les noms d’utilisateur et l’utilisation, jamais les trades ni les notes.","Los datos de cada trader están separados. La página de admin muestra usuarios y uso, nunca operaciones ni notas.")),
        ("key",T("Passwords are never readable","Mots de passe jamais lisibles","Contraseñas nunca legibles"),T("Stored only as a secure hash. Resets use a one-time link valid for one hour.","Conservés uniquement sous forme de hachage sécurisé. Les réinitialisations utilisent un lien unique valide une heure.","Se guardan solo como hash seguro. Los restablecimientos usan un enlace único válido una hora.")),
        ("shield",T("Protected sign-in","Connexion protégée","Acceso protegido"),T("A new browser asks for a 6-digit code sent by email, then is remembered for 30 days; Face ID in the app on your home screen. HTTPS only, limits on attempts and anti-bot checks.","Un nouveau navigateur demande un code à 6 chiffres envoyé par courriel, puis est reconnu 30 jours ; Face ID dans l’app ajoutée à l’écran d’accueil. HTTPS seulement, limites de tentatives et protection anti-robots.","Un navegador nuevo pide un código de 6 dígitos enviado por correo y luego queda reconocido 30 días; Face ID en la app añadida a tu pantalla de inicio. Solo HTTPS, límites de intentos y protección antibots.")),
        ("image",T("Private screenshots","Captures privées","Capturas privadas"),T("Images you attach to trades are stored privately for your account only.","Les images jointes à tes trades sont conservées en privé, pour ton compte seulement.","Las imágenes que adjuntas se guardan en privado, solo para tu cuenta.")),
        ("layers",T("Social is opt-in","Le social est opt-in","Lo social es opcional"),T("Leagues, crews, buddies and your public profile stay off until you turn them on. Others never see your P&L, amounts, trades or accounts.","Ligues, crews, buddies et profil public restent éteints tant que tu ne les actives pas. Les autres ne voient jamais ton P&L, tes montants, tes trades ou tes comptes.","Ligas, crews, buddies y tu perfil público siguen apagados hasta que los activas. Los demás nunca ven tu P&L, importes, operaciones ni cuentas.")),
        ("download",T("Export everything","Exporte tout","Exporta todo"),T("One click gives you a ZIP file: a re-importable backup, CSV spreadsheets (trades, accounts, payouts, expenses, journal) and all your screenshots.","Un clic te donne un fichier ZIP : sauvegarde réimportable, tableurs CSV (trades, comptes, payouts, dépenses, journal) et toutes tes captures.","Un clic te da un archivo ZIP: copia reimportable, hojas CSV (operaciones, cuentas, payouts, gastos, diario) y todas tus capturas.")),
        ("trash",T("Delete instantly","Supprime instantanément","Elimina al instante"),T("Self-serve deletion in Settings removes everything, screenshots included, right away. Your password is required.","Réglages → Supprimer mon compte efface tout, captures comprises, tout de suite. Ton mot de passe est requis.","Ajustes → Eliminar mi cuenta lo borra todo, capturas incluidas, al instante. Se requiere tu contraseña."))]
    rows = [(T("Account","Compte","Cuenta"),T("Username, email, password hash, first name, trading experience, language, date you accepted the terms","Nom d’utilisateur, courriel, hachage du mot de passe, prénom, expérience de trading, langue, date d’acceptation des conditions","Usuario, correo, hash de contraseña, nombre de pila, experiencia en trading, idioma, fecha de aceptación de los términos")),
            (T("What you enter","Ce que tu saisis","Lo que introduces"),T("Accounts, trades, journals, payouts, expenses, settings and screenshots","Comptes, trades, journaux, payouts, dépenses, réglages et captures","Cuentas, operaciones, diarios, payouts, gastos, ajustes y capturas")),
            (T("Technical","Technique","Técnico"),T("IP addresses kept up to 24 hours, only to limit sign-in attempts","Adresses IP gardées jusqu’à 24 heures, seulement pour limiter les tentatives de connexion","Direcciones IP guardadas hasta 24 horas, solo para limitar intentos de acceso")),
            (T("Sign-in security","Sécurité de connexion","Seguridad de acceso"),T("Your remembered browsers (browser, system, last use), one-time sign-in codes valid 10 minutes and, with Face ID, a public key only","Tes navigateurs reconnus (navigateur, système, dernière utilisation), les codes de connexion valides 10 minutes et, avec Face ID, une clé publique seulement","Tus navegadores reconocidos (navegador, sistema, último uso), códigos de acceso válidos 10 minutos y, con Face ID, solo una clave pública")),
            (T("On your device","Sur ton appareil","En tu dispositivo"),T("A session cookie (30 days), a remembered-browser cookie (30 days), interface preferences (theme, language, filters, last account) and, if you came from a campaign link, a sweep_utm cookie with its campaign tags (30 days)","Un témoin de session (30 jours), un témoin de navigateur reconnu (30 jours), tes préférences (thème, langue, filtres, dernier compte) et, si tu arrives d’un lien de campagne, un témoin sweep_utm avec ses étiquettes (30 jours)","Una cookie de sesión (30 días), una cookie de navegador reconocido (30 días), preferencias (tema, idioma, filtros, última cuenta) y, si llegas desde un enlace de campaña, una cookie sweep_utm con sus etiquetas (30 días)")),
            (T("Where","Où","Dónde"),T("Sweep’s server at HostArmada. The database sits outside the public web folder","Le serveur de Sweep chez HostArmada. La base de données est hors du dossier web public","El servidor de Sweep en HostArmada. La base de datos está fuera de la carpeta web pública")),
            (T("Third parties","Tiers","Terceros"),T("Stripe for payments (Sweep never sees your card number); Discord, only if you connect your account; Google (Gemini API, Google Search) when you use an AI feature and to prepare economic reports; your phone’s push service (Apple, Google or Mozilla), if you turn on notifications. No analytics, no ads, no trackers, no data sold. Emails are sent from Sweep’s own server","Stripe pour les paiements (Sweep ne voit jamais ton numéro de carte) ; Discord, seulement si tu connectes ton compte ; Google (API Gemini, Recherche Google) quand tu utilises une fonction IA et pour préparer les rapports économiques ; le service de notifications de ton téléphone (Apple, Google ou Mozilla), si tu actives les notifications. Aucune analytique, aucune pub, aucun traqueur, aucune donnée vendue. Les courriels partent du serveur de Sweep","Stripe para los pagos (Sweep nunca ve tu número de tarjeta); Discord, solo si conectas tu cuenta; Google (API Gemini, Búsqueda de Google) cuando usas una función de IA y para preparar los informes económicos; el servicio de notificaciones de tu teléfono (Apple, Google o Mozilla), si activas las notificaciones. Sin analítica, anuncios, rastreadores ni venta de datos. Los correos salen del servidor de Sweep")),
            (T("Visible to others","Visible par les autres","Visible para otros"),T("Leagues, crews or a buddy, only if you join: your username, rank and consistency (a buddy also sees your rings and streak), never P&L, amounts, trades or accounts. Your public profile and share links, only if you create them: the profile never shows an amount, and a share card hides amounts unless you choose to show them","Ligues, crews ou buddy, seulement si tu les rejoins : ton pseudo, ton rang et ta régularité (un buddy voit aussi tes anneaux et ton streak), jamais de P&L, de montants, de trades ni de comptes. Ton profil public et tes liens de partage, seulement si tu les crées : le profil ne montre jamais un montant, et une carte masque les montants sauf si tu choisis de les afficher","Ligas, crews o un buddy, solo si te unes: tu usuario, tu rango y tu constancia (un buddy también ve tus anillos y tu racha), nunca P&L, importes, operaciones ni cuentas. Tu perfil público y tus enlaces para compartir, solo si los creas: el perfil nunca muestra un importe, y una tarjeta oculta los importes salvo que elijas mostrarlos")),
            (T("Sweep AI","Sweep AI","Sweep AI"),T("Nothing is sent until you tap an AI action, then only what it needs. Ask Sweep conversations stay in your browser for the session. Deleting your account deletes its AI history","Rien n’est envoyé avant que tu touches une action IA, puis seulement le nécessaire. Les discussions Ask Sweep restent dans ton navigateur pour la session. Supprimer ton compte supprime son historique IA","No se envía nada hasta que tocas una acción de IA, y luego solo lo necesario. Las conversaciones de Ask Sweep quedan en tu navegador durante la sesión. Eliminar tu cuenta elimina su historial de IA"))]
    tbl = '<table class="tbl"><tbody>' + "".join(f"<tr><th>{t(a)}</th><td>{t(c)}</td></tr>" for a,c in rows) + "</tbody></table>"
    hero = ui.hero(t, H[2], H[0], H[1], cta=ui.btn(t(CREATE_FREE), SIGNUP, lg=True))
    b = (ui.sec(ui.cards([ui.card(t, a, c, k) for k, a, c in items], 3), "t", "protection")
         + ui.sec(ui.head(t, None, T("What we store","Ce que nous conservons","Qué guardamos")) + tbl + f'<p class="fine" style="margin-top:28px"><a href="{href(lang,"privacy.html")}">{t(T("Read the full privacy policy","Lire la politique de confidentialité complète","Leer la política de privacidad completa"))}</a></p>', "n", "store", width="read") + ui.final(lang, t))
    return (t(T("Security and privacy · Sweep","Sécurité et confidentialité · Sweep","Seguridad y privacidad · Sweep")),
            t(T("How Sweep protects your trading data: private by default, hashed passwords, ZIP export, instant account deletion, no ads or trackers.","Comment Sweep protège tes données de trading : privé par défaut, mots de passe hachés, export ZIP, suppression immédiate, ni pubs ni traqueurs.","Cómo Sweep protege tus datos de trading: privado por defecto, contraseñas con hash, exportación ZIP, eliminación inmediata, sin anuncios ni rastreadores.")),
            hero + b, "")

SYSTEM_PAGES.add("security.html")

ABOUT_HELP = T("""<h2>How we build Sweep</h2><p>New versions ship regularly, and every release is listed in <a href="@changelog.html">What’s new</a>. Ideas and bug reports sent from the app are kept with their status, so the traders who asked know when it ships. Prop firm rules are checked every week against each firm’s official pages, and the whole app is in English, French and Spanish.</p>
<h2>Who Sweep is for</h2><p>Futures traders, from the first evaluation to a live funded account: prop traders who juggle several firms and accounts, and traders on personal accounts who want honest numbers. Sweep doesn’t trade for you, doesn’t give signals and never sells your data.</p>""",
"""<h2>Comment on construit Sweep</h2><p>De nouvelles versions sortent régulièrement, et chacune est listée dans les <a href="@changelog.html">Nouveautés</a>. Les idées et les bugs envoyés depuis l’app sont gardés avec leur statut, pour que les traders qui les ont demandés sachent quand c’est livré. Les règles des prop firms sont vérifiées chaque semaine sur les pages officielles de chaque firme, et toute l’app existe en français, en anglais et en espagnol.</p>
<h2>Pour qui est Sweep</h2><p>Les traders de futures, de la première évaluation jusqu’au compte financé en live : les traders prop qui jonglent avec plusieurs firmes et plusieurs comptes, et les traders sur compte personnel qui veulent des chiffres honnêtes. Sweep ne trade pas à ta place, ne donne pas de signaux et ne vend jamais tes données.</p>""",
"""<h2>Cómo construimos Sweep</h2><p>Salen versiones nuevas con frecuencia, y cada una aparece en <a href="@changelog.html">Novedades</a>. Las ideas y los errores enviados desde la app se guardan con su estado, para que los traders que los pidieron sepan cuándo están listos. Las reglas de las prop firms se revisan cada semana en las páginas oficiales de cada firma, y toda la app está en español, inglés y francés.</p>
<h2>Para quién es Sweep</h2><p>Para traders de futuros, desde la primera evaluación hasta una cuenta financiada en real: traders prop que gestionan varias firmas y cuentas, y traders con cuenta personal que quieren cifras honestas. Sweep no opera por ti, no da señales y nunca vende tus datos.</p>""")

def page_about(lang, t):
    story = T("""<p><b>Sweep started as one trader’s journal.</b> It was built for a small community of futures traders who were tired of spreadsheets, scattered screenshots, and firm dashboards that disappeared with every prop account.</p>
<p>The name comes from market structure. A sweep takes the liquidity below a level before price moves higher. Trading works the same way: the losing days, the broken rules and the lessons are the low that gets swept. What you do with them is the move that follows.</p>
<p>Sweep is built in Quebec by Sweep Inc. It exists to make that next move easier: <a href="features.html">one place for every trade, rule, account and payout</a>, an honest look at what works, and a history you keep no matter what happens to an account.</p>""",
"""<p><b>Sweep a commencé comme le journal d’un trader.</b> Il a été conçu pour une petite communauté de traders de futures, tannés des tableurs, des captures éparpillées et des tableaux de bord qui disparaissaient avec chaque compte prop.</p>
<p>Le nom vient de la structure de marché. Un sweep va chercher la liquidité sous un niveau avant que le prix monte. Le trading fonctionne pareil : les journées perdantes, les règles brisées et les leçons sont le creux qui se fait balayer. Ce que tu en fais, c’est le mouvement qui suit.</p>
<p>Sweep est conçu au Québec par Sweep Inc. Il existe pour rendre ce prochain mouvement plus facile : <a href="features.html">un seul endroit pour chaque trade, règle, compte et payout</a>, un regard honnête sur ce qui marche, et un historique que tu gardes peu importe ce qui arrive à un compte.</p>""",
"""<p><b>Sweep empezó como el diario de un trader.</b> Se creó para una pequeña comunidad de traders de futuros, cansados de hojas de cálculo, capturas dispersas y paneles que desaparecían con cada cuenta prop.</p>
<p>El nombre viene de la estructura de mercado. Un sweep toma la liquidez bajo un nivel antes de que el precio suba. El trading funciona igual: los días perdedores, las reglas rotas y las lecciones son el mínimo que se barre. Lo que haces con ellos es el movimiento que sigue.</p>
<p>Sweep se crea en Quebec por Sweep Inc. Existe para facilitar ese siguiente movimiento: <a href="features.html">un solo lugar para cada operación, regla, cuenta y payout</a>, una mirada honesta a lo que funciona y un historial que conservas pase lo que pase con una cuenta.</p>""")
    import ui
    hero = ui.hero(t, T("About","À propos","Acerca de"), T("About Sweep","À propos de Sweep","Acerca de Sweep"), T("Why Sweep exists, and what it will never do.","Pourquoi Sweep existe, et ce qu’il ne fera jamais.","Por qué existe Sweep y lo que nunca hará."),
                   cta=ui.btn(t(CREATE_FREE), SIGNUP, lg=True, attrs='data-track="signup_about_hero"'))
    ident = T("<p><b>Sweep is a <a href=\"index.html\">free trading journal</a> built for futures and prop firm traders, with firm rules checked every week.</b> It was born in a Discord community of futures traders, tested for months by trader friends before it had a name, and <a href=\"changelog.html\">launched publicly on October 1, 2026</a>.</p><p><b>Our mission:</b> give every trader the system to become consistently profitable: build the habits, find the edge, get the payouts, track the expenses, and never lose a trading history again.</p>",
              "<p><b>Sweep est un <a href=\"index.html\">journal de trading gratuit</a> conçu pour les traders de futures et de prop firms, avec les règles des firmes vérifiées chaque semaine.</b> Il est né dans une communauté Discord de traders de futures, a été testé pendant des mois par des amis traders avant même d’avoir un nom, et a été <a href=\"changelog.html\">lancé publiquement le 1er octobre 2026</a>.</p><p><b>Notre mission :</b> donner à chaque trader le système pour devenir régulièrement rentable : bâtir les habitudes, trouver son edge, obtenir ses payouts, suivre ses dépenses, et ne plus jamais perdre son historique.</p>",
              "<p><b>Sweep es un <a href=\"index.html\">diario de trading gratuito</a> creado para traders de futuros y de prop firms, con las reglas de las firmas revisadas cada semana.</b> Nació en una comunidad de Discord de traders de futuros, lo probaron durante meses amigos traders antes de tener nombre y se <a href=\"changelog.html\">lanzó públicamente el 1 de octubre de 2026</a>.</p><p><b>Nuestra misión:</b> dar a cada trader el sistema para ser rentable de forma constante: crear los hábitos, encontrar su ventaja, cobrar sus payouts, seguir sus gastos y no volver a perder su historial.</p>")
    company = (f'<h2>{t(T("The company","L’entreprise","La empresa"))}</h2><p>Sweep Inc.<br>3980 Blvd St-Elzear O, Laval (Québec) H7P 0M2, Canada<br>'
               f'<a href="mailto:{EMAIL}">{EMAIL}</a> · <a href="{href(lang, "press-kit.html")}">{t(T("Press kit","Kit presse","Kit de prensa"))}</a></p>')   # a few lines: at the end of the story, not a section of its own
    about = re.sub(r'href="([a-z]+\.html)"', lambda m: f'href="{href(lang, m.group(1))}"', t(ident) + t(story))
    believe = [("archive",T("Your data stays yours","Tes données restent à toi","Tus datos son tuyos"),T("Private, exportable, deletable, never sold.","Privées, exportables, supprimables, jamais vendues.","Privados, exportables, eliminables, nunca vendidos.")),
               ("check",T("Honest numbers","Des chiffres honnêtes","Números honestos"),T("The bad days count. A warning never hides a broken rule.","Les mauvaises journées comptent. Un avertissement ne cache jamais une règle brisée.","Los días malos cuentan. Un aviso nunca oculta una regla rota.")),
               ("bolt",T("No signals, no hype","Ni signaux ni hype","Sin señales ni exageraciones"),T("Sweep shows your data. The decisions stay yours.","Sweep montre tes données. Les décisions restent les tiennes.","Sweep muestra tus datos. Las decisiones son tuyas."))]
    b = (ui.sec(f'<article class="article">{about}{company}</article>', "t", "story", width="read")
         + ui.sec(ui.frame_d("v6-01-today-d.webp", t(T("Sweep, the Today screen, sample data","Sweep, l’écran Aujourd’hui, données d’exemple","Sweep, la pantalla Hoy, datos de ejemplo")), m="v6-01-today-m.webp", t=t, sizes="(max-width: 1067px) 92vw, 1200px"), "n", "app", width="wide")
         + ui.sec(ui.head(t, None, T("What we believe","Ce en quoi on croit","En qué creemos")) + ui.cards([ui.card(t, a, d, icon=k) for k, a, d in believe], 3), "n", "believe")
         + ui.sec(f'<article class="article">{localize(lang, t(ABOUT_HELP))}</article>', "n", "how", width="read"))
    return (t(T("About Sweep","À propos de Sweep","Acerca de Sweep")), t(T("Sweep is a trading journal built in Quebec by a futures trader, for futures and prop traders.","Sweep est un journal de trading conçu au Québec par un trader de futures, pour les traders de futures et prop.","Sweep es un diario de trading creado en Quebec por un trader de futuros, para traders de futuros y prop.")), hero + b + ui.final(lang, t), "")
SYSTEM_PAGES.add("about.html")

CONTACT_HELP = T("""<h2>Get a faster answer</h2><ul>
<li><b>Say which account.</b> Your Sweep username or the email you signed up with. Never send your password: we don’t need it to help you.</li>
<li><b>Describe what you see.</b> The screen, what you expected, what happened instead, and a screenshot if you can.</li>
<li><b>Add your device.</b> Phone or computer, and the browser (Safari, Chrome, Edge…).</li>
<li><b>For an import or a sync,</b> name the platform (Tradovate, TopstepX, Rithmic, NinjaTrader 8, Quantower…) and the firm.</li>
<li><b>One topic per message</b> keeps the thread easy to follow.</li></ul>
<h2>Answers you may find right away</h2><p>Importing trades: <a href="@import.html">how to import your trades</a>. Sweep on your phone: <a href="@install.html">install it in three taps</a>. Your data, export and deletion: <a href="@security.html">security and data</a>. A firm’s current rules: the <a href="@prop-firms/index.html">prop firm rules pages</a>. Everything else: the <a href="@faq.html">FAQ</a>.</p>
<h2>Ideas and bugs, from the app</h2><p>You can also send an idea or a bug report from inside Sweep. We keep each one with its status, so we can follow up and tell you when it ships.</p>
<h2>A firm’s rule looks wrong?</h2><p>Tell us the firm, the account type and the page where you read the rule. We check it against the firm’s official pages and fix the preset for every trader.</p>
<h2>A question about a charge?</h2><p>Write to us from the email on your account with the date and the amount of the charge. Never send your card number: we don’t need it.</p>
<h2>Privacy requests</h2><p>To access, correct or delete your personal information, write to us from the email on your account, so we know it’s you. You can also export everything or delete your account yourself, in Settings. We answer privacy requests within 30 days.</p>""",
"""<h2>Pour une réponse plus rapide</h2><ul>
<li><b>Dis-nous quel compte.</b> Ton nom d’utilisateur Sweep ou le courriel de ton inscription. N’envoie jamais ton mot de passe : on n’en a pas besoin pour t’aider.</li>
<li><b>Décris ce que tu vois.</b> L’écran, ce que tu attendais, ce qui s’est passé à la place, et une capture si tu peux.</li>
<li><b>Précise ton appareil.</b> Téléphone ou ordinateur, et le navigateur (Safari, Chrome, Edge…).</li>
<li><b>Pour un import ou une synchro,</b> nomme la plateforme (Tradovate, TopstepX, Rithmic, NinjaTrader 8, Quantower…) et la firme.</li>
<li><b>Un sujet par message</b> garde l’échange facile à suivre.</li></ul>
<h2>Des réponses tout de suite</h2><p>Importer tes trades : <a href="@import.html">comment importer tes trades</a>. Sweep sur ton téléphone : <a href="@install.html">l’installer en trois touchers</a>. Tes données, l’export et la suppression : <a href="@security.html">sécurité et données</a>. Les règles actuelles d’une firme : les <a href="@prop-firms/index.html">pages de règles des prop firms</a>. Tout le reste : la <a href="@faq.html">FAQ</a>.</p>
<h2>Idées et bugs, depuis l’app</h2><p>Tu peux aussi envoyer une idée ou signaler un bug directement dans Sweep. On garde chacun avec son statut, pour y donner suite et te dire quand c’est livré.</p>
<h2>Une règle de firme te semble fausse ?</h2><p>Dis-nous la firme, le type de compte et la page où tu as lu la règle. On la vérifie sur les pages officielles de la firme et on corrige le préréglage pour tous les traders.</p>
<h2>Une question sur un paiement ?</h2><p>Écris-nous depuis le courriel de ton compte, avec la date et le montant du paiement. N’envoie jamais ton numéro de carte : on n’en a pas besoin.</p>
<h2>Demandes de confidentialité</h2><p>Pour consulter, corriger ou supprimer tes renseignements personnels, écris-nous depuis le courriel de ton compte, pour qu’on sache que c’est toi. Tu peux aussi tout exporter ou supprimer ton compte toi-même, dans les Réglages. On répond aux demandes de confidentialité dans un délai de 30 jours.</p>""",
"""<h2>Para una respuesta más rápida</h2><ul>
<li><b>Dinos qué cuenta.</b> Tu usuario de Sweep o el correo con el que te registraste. No envíes nunca tu contraseña: no la necesitamos para ayudarte.</li>
<li><b>Describe lo que ves.</b> La pantalla, lo que esperabas, lo que pasó en su lugar y una captura si puedes.</li>
<li><b>Indica tu dispositivo.</b> Teléfono u ordenador, y el navegador (Safari, Chrome, Edge…).</li>
<li><b>Para una importación o una sincronización,</b> indica la plataforma (Tradovate, TopstepX, Rithmic, NinjaTrader 8, Quantower…) y la firma.</li>
<li><b>Un tema por mensaje</b> hace que la conversación sea fácil de seguir.</li></ul>
<h2>Respuestas al momento</h2><p>Importar operaciones: <a href="@import.html">cómo importar tus operaciones</a>. Sweep en tu teléfono: <a href="@install.html">instálalo en tres toques</a>. Tus datos, la exportación y el borrado: <a href="@security.html">seguridad y datos</a>. Las reglas actuales de una firma: las <a href="@prop-firms/index.html">páginas de reglas de las prop firms</a>. Todo lo demás: las <a href="@faq.html">preguntas frecuentes</a>.</p>
<h2>Ideas y errores, desde la app</h2><p>También puedes enviar una idea o avisar de un error desde dentro de Sweep. Guardamos cada uno con su estado para darle seguimiento y avisarte cuando esté listo.</p>
<h2>¿Una regla de una firma parece incorrecta?</h2><p>Dinos la firma, el tipo de cuenta y la página donde leíste la regla. La revisamos en las páginas oficiales de la firma y corregimos el preajuste para todos los traders.</p>
<h2>¿Una pregunta sobre un cobro?</h2><p>Escríbenos desde el correo de tu cuenta con la fecha y el importe del cobro. No envíes nunca el número de tu tarjeta: no lo necesitamos.</p>
<h2>Solicitudes de privacidad</h2><p>Para consultar, corregir o eliminar tu información personal, escríbenos desde el correo de tu cuenta, para saber que eres tú. También puedes exportarlo todo o eliminar tu cuenta tú mismo, en Ajustes. Respondemos a las solicitudes de privacidad en un plazo de 30 días.</p>""")

def page_contact(lang, t):
    import ui
    hero = ui.hero(t, T("Contact","Contact","Contacto"), T("Talk to us.","Écris-nous.","Escríbenos."), T("Questions, feedback, a bug or a feature you need. A real person reads every message.","Questions, commentaires, un bug ou une fonctionnalité qui te manque. Une vraie personne lit chaque message.","Preguntas, comentarios, un error o una función que necesitas. Una persona real lee cada mensaje."))
    press = {l: {"en": "Journalists: see the", "fr": "Journalistes : voir le", "es": "Periodistas: consulta el"}[l] + f' <a href="{href(l, "press-kit.html")}">' + {"en": "press kit", "fr": "kit presse", "es": "kit de prensa"}[l] + "</a>." for l in LANGS}
    mail = {l: {"en": "Support, accounts, privacy requests and feedback.", "fr": "Soutien, comptes, demandes de confidentialité et commentaires.", "es": "Soporte, cuentas, solicitudes de privacidad y comentarios."}[l] + " " + press[l] for l in LANGS}
    cards = ui.cards([ui.card(t, T("Email","Courriel","Correo"), mail, icon="globe", more=f'<a class="btn btn-line" href="mailto:{EMAIL}">{EMAIL}</a>'),
                      ui.card(t, T("Account help","Aide pour ton compte","Ayuda con tu cuenta"), T("Forgot your password? Use “Forgot password?” on the log-in screen to get a reset link by email.","Mot de passe oublié ? Utilise « Mot de passe oublié ? » sur l’écran de connexion pour recevoir un lien par courriel.","¿Olvidaste tu contraseña? Usa «¿Olvidaste tu contraseña?» en la pantalla de inicio para recibir un enlace por correo."),
                              icon="key", more=f'<a class="btn btn-line" href="{APP}">{t(LOGIN)}</a>')], 2)
    follow = ui.band(t(T("Follow Sweep","Suis Sweep","Sigue a Sweep")), t(T(f"Tips, product updates and <a href=\"{href(lang, '100')}\">the first 100</a>, on Instagram, TikTok and Facebook.",f"Conseils, nouveautés et <a href=\"{href(lang, '100')}\">les 100 premiers</a>, sur Instagram, TikTok et Facebook.",f"Consejos, novedades y <a href=\"{href(lang, '100')}\">los primeros 100</a>, en Instagram, TikTok y Facebook.")), social_links("social big", t))
    b = (ui.sec(cards + follow + f'<p class="fine" style="margin-top:24px"><a href="{href(lang, "about.html")}">Sweep Inc.</a> · 3980 Blvd St-Elzear O, Laval (Québec) H7P 0M2, Canada</p>', "t", "contact")
         + ui.sec(f'<article class="article">{localize(lang, t(CONTACT_HELP))}</article>', "n", "help", width="read"))
    return (t(T("Contact Sweep","Contacter Sweep","Contactar con Sweep")), t(T(f"Contact the Sweep team at {EMAIL} for support, privacy requests, press and feedback. Write to us in English, French or Spanish.",f"Joins l’équipe Sweep à {EMAIL} pour du soutien, une demande de confidentialité, la presse ou tes commentaires, en français, en anglais ou en espagnol.",f"Contacta al equipo de Sweep en {EMAIL} para soporte, privacidad, prensa y comentarios. Escríbenos en español, inglés o francés.")), hero + b + ui.final(lang, t), "")
SYSTEM_PAGES.add("contact.html")

